  return 2*(N+V)*B + 4*S*B*0    # per step, GEMM part\nprint(\"== per-call FLOPs (GFLOP) ==\")\nfor n,N in M.items():\n    for S in [128,1024,2048,4096]:\n        print(f\"  {n:4} prefill S={S:4} B=1: {prefill_flops(N,S,1)/1e9:9.1f}   B=8: {prefill_flops(N,S,8)/1e9:9.1f}\")\n    for S in [128,4096]:\n        print(f\"  {n:4} decode-step/seq S={S:4}: {(2*(N+V))/1e9:7.2f} GEMM + attn {4*32*S*4096/1e9:.2f}(7B-ish, indicative)\")\nprint()\nprint(\"== GPU-hour budget model (placeholder utilizations) ==\")\ndef arm_hours(N,S_list,B_list,steps,util,fp):\n    h=0\n    for S in S_list: h+= prefill_flops(N,S,max(B_list))*steps['pre']/ (fp*util*3600)\n    for S in S_list:\n        for B in B_list: h+= 2*(N+V)*B*steps['dec'][S]/(fp*util*3600)\n    return h\nS=[128,1024,2048,4096]; B=[1,8,32,64]; steps={'pre':30,'dec':{128:128,1024:128,2048:128,4096:256}}\nfor hn,fp in [(\"A100\",312e12)]:\n  for n,N in M.items():\n    for u in (0.4,0.6):\n        print(f\"  {hn} {n:4} util={u}: {(arm_hours(N,S,B,steps,u,fp)):.2f} GPUh per arm-rep (perf only, excl. quant+PPL)\")\nprint()\nprint(\"== quantization+PPL offline cost (analytic) ==\")\nfor n,N in M.items():\n    print(f\"  {n:4}: calib fwd 128x2048 = {2*N*128*2048/1e18:.3f} EFLOP; WikiPPL 2048x512 = {2*N*2048*512/1e18:.3f} EFLOP; C4 11kx4096 = {2*N*11000*4096/1e18:.2f} EFLOP\")\nPY\npython3 /tmp/dry/b.py", "timeout_seconds": 60, "kind": "ExecuteCheckAction"}, "tool_name": "execute_check", "tool_call_id": "chatcmpl-tool-97dffc56a2f92f09", "tool_call": {"id": "chatcmpl-tool-97dffc56a2f92f09", "responses_item_id": null, "name": "execute_check", "arguments": "{\"command\": \"mkdir -p /tmp/dry && cat > /tmp/dry/b.py <<'PY'\\nM={\\\"7B\\\":6.48e9,\\\"13B\\\":12.69e9,\\\"70B\\\":77.85e9}   # non-embedding params (analytic)\\nV=32000\\ndef prefill_flops(N,S,B): return 2*(N+2*V*0.5)*S*B     # ~2*N per token (+lm_head)\\ndef decode_flops(N,S,B):  return 2*(N+V)*B + 4*S*B*0    # per step, GEMM part\\nprint(\\\"== per-call FLOPs (GFLOP) ==\\\")\\